import{_ as t,C as p,o as e,c as l,a5 as a,E as i}from"./chunks/framework.Bhkz_BpM.js";const v=JSON.parse('{"title":"MS-05 参数自整定与仿真验证","description":"","frontmatter":{"title":"MS-05 参数自整定与仿真验证","date":"2026-07-09T00:00:00.000Z","quality":"curated","status":"learning","visibility":"public","order":60,"summary":"从手动参数扫描开始理解自整定，把指标函数、参数范围、日志记录和结果复核连成一条可靠流程。"},"headers":[],"relativePath":"content/matlab-simulink/tuning-validation/MS-05-Parameter-Auto-Tuning.md","filePath":"content/matlab-simulink/tuning-validation/MS-05-Parameter-Auto-Tuning.md","lastUpdated":null}'),m={name:"content/matlab-simulink/tuning-validation/MS-05-Parameter-Auto-Tuning.md"};function r(c,s,o,h,d,g){const n=p("MermaidDiagram");return e(),l("div",null,[s[0]||(s[0]=a(`<h1 id="ms-05-参数自整定与仿真验证" tabindex="-1">MS-05 参数自整定与仿真验证 <a class="header-anchor" href="#ms-05-参数自整定与仿真验证" aria-label="Permalink to &quot;MS-05 参数自整定与仿真验证&quot;">​</a></h1><p>参数自整定不是按一个按钮得到完美参数。它的核心是定义目标、约束范围、批量仿真、比较指标，再回到模型检查结果是否可信。</p><h2 id="_1-先写指标函数" tabindex="-1">1. 先写指标函数 <a class="header-anchor" href="#_1-先写指标函数" aria-label="Permalink to &quot;1. 先写指标函数&quot;">​</a></h2><p>在控制系统里，一个简单指标可以由误差、控制量和超调组成：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>J</mi><mo>=</mo><msub><mi>w</mi><mi>e</mi></msub><munder><mo>∑</mo><mi>k</mi></munder><mi>e</mi><mo stretchy="false">[</mo><mi>k</mi><msup><mo stretchy="false">]</mo><mn>2</mn></msup><msub><mi>T</mi><mi>s</mi></msub><mo>+</mo><msub><mi>w</mi><mi>u</mi></msub><munder><mo>∑</mo><mi>k</mi></munder><mi>u</mi><mo stretchy="false">[</mo><mi>k</mi><msup><mo stretchy="false">]</mo><mn>2</mn></msup><msub><mi>T</mi><mi>s</mi></msub><mo>+</mo><msub><mi>w</mi><mi>o</mi></msub><msub><mi>M</mi><mi>p</mi></msub></mrow><annotation encoding="application/x-tex">J = w_e \\sum_k e[k]^2 T_s + w_u \\sum_k u[k]^2 T_s + w_o M_p</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3521em;vertical-align:-1.3021em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">e</span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose"><span class="mclose">]</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.3521em;vertical-align:-1.3021em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">u</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">u</span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose"><span class="mclose">]</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">o</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span></span><p>其中 <code>e[k]</code> 是误差，<code>u[k]</code> 是控制量，<code>M_p</code> 是超调。权重不是越多越好，新手先用三项就够。</p><h2 id="_2-参数扫描" tabindex="-1">2. 参数扫描 <a class="header-anchor" href="#_2-参数扫描" aria-label="Permalink to &quot;2. 参数扫描&quot;">​</a></h2><p>先做网格扫描，比直接用优化器更容易理解。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KpList = linspace(0.2, 2.0, 10);</span></span>
<span class="line"><span>KiList = linspace(5, 80, 10);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>best.J = inf;</span></span>
<span class="line"><span>for i = 1:numel(KpList)</span></span>
<span class="line"><span>    for j = 1:numel(KiList)</span></span>
<span class="line"><span>        result = run_case(KpList(i), KiList(j));</span></span>
<span class="line"><span>        if result.J &lt; best.J</span></span>
<span class="line"><span>            best = result;</span></span>
<span class="line"><span>        end</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>disp(best);</span></span></code></pre></div><p><code>run_case</code> 应该返回曲线和指标，而不是只返回一个分数。否则你可能得到一个分数很低但波形不可接受的参数。</p><h2 id="_3-从扫描到自整定" tabindex="-1">3. 从扫描到自整定 <a class="header-anchor" href="#_3-从扫描到自整定" aria-label="Permalink to &quot;3. 从扫描到自整定&quot;">​</a></h2><p>常见流程如下：</p>`,12)),i(n,{code:"flowchart%20LR%0A%20%20Range%5B%22%E8%AE%BE%E7%BD%AE%E5%8F%82%E6%95%B0%E8%8C%83%E5%9B%B4%22%5D%20--%3E%20Batch%5B%22%E6%89%B9%E9%87%8F%E4%BB%BF%E7%9C%9F%22%5D%0A%20%20Batch%20--%3E%20Metric%5B%22%E8%AE%A1%E7%AE%97%E6%8C%87%E6%A0%87%22%5D%0A%20%20Metric%20--%3E%20Pick%5B%22%E9%80%89%E6%8B%A9%E5%80%99%E9%80%89%E5%8F%82%E6%95%B0%22%5D%0A%20%20Pick%20--%3E%20Review%5B%22%E5%A4%8D%E6%A0%B8%E6%B3%A2%E5%BD%A2%E5%92%8C%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20Review%20--%3E%20Narrow%5B%22%E7%BC%A9%E5%B0%8F%E8%8C%83%E5%9B%B4%22%5D%0A%20%20Narrow%20--%3E%20Batch%0A"}),s[1]||(s[1]=a(`<p>自动化的重点是减少重复劳动，不是取消判断。每轮扫描后都要看候选波形，确认没有靠过度饱和、过大控制量或模型漏洞拿到好分数。</p><h2 id="_4-结果表格" tabindex="-1">4. 结果表格 <a class="header-anchor" href="#_4-结果表格" aria-label="Permalink to &quot;4. 结果表格&quot;">​</a></h2><p>建议每次输出一张表：</p><div class="kb-table-scroll"><table><thead><tr><th>Kp</th><th>Ki</th><th>超调</th><th>调节时间</th><th>稳态误差</th><th>控制量峰值</th><th>指标 J</th></tr></thead><tbody><tr><td>0.8</td><td>30</td><td>0.04</td><td>0.18 s</td><td>0.002</td><td>0.72</td><td>1.35</td></tr><tr><td>1.2</td><td>45</td><td>0.11</td><td>0.12 s</td><td>0.001</td><td>1.00</td><td>1.42</td></tr><tr><td>0.5</td><td>20</td><td>0.00</td><td>0.35 s</td><td>0.004</td><td>0.48</td><td>1.80</td></tr></tbody></table></div><p>看表格时不要只看 <code>J</code> 最小。控制量峰值贴近饱和、超调过大、调节时间太长，都可能让参数不适合实机。</p><h2 id="_5-simulink-批量仿真接口" tabindex="-1">5. Simulink 批量仿真接口 <a class="header-anchor" href="#_5-simulink-批量仿真接口" aria-label="Permalink to &quot;5. Simulink 批量仿真接口&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>model = &quot;discrete_pi_model&quot;;</span></span>
<span class="line"><span>in = Simulink.SimulationInput(model);</span></span>
<span class="line"><span>in = in.setVariable(&quot;Kp&quot;, 0.8);</span></span>
<span class="line"><span>in = in.setVariable(&quot;Ki&quot;, 30.0);</span></span>
<span class="line"><span>in = in.setVariable(&quot;Ts&quot;, 1e-3);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>out = sim(in);</span></span>
<span class="line"><span>logs = out.logsout;</span></span></code></pre></div><p>批量仿真时，参数要从脚本传入模型，不要手动改模块对话框。这样每次实验都可复现，也方便以后接入优化器。</p><h2 id="_6-自整定验收" tabindex="-1">6. 自整定验收 <a class="header-anchor" href="#_6-自整定验收" aria-label="Permalink to &quot;6. 自整定验收&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>验收项</th><th>说明</th></tr></thead><tbody><tr><td>参数范围合理</td><td>不搜索明显不可能的区域</td></tr><tr><td>指标函数可解释</td><td>每一项都对应真实需求</td></tr><tr><td>候选波形可接受</td><td>不是只看单个分数</td></tr><tr><td>饱和次数可统计</td><td>避免参数依赖长期饱和</td></tr><tr><td>结果可复现</td><td>同一脚本重复运行得到同一候选</td></tr></tbody></table></div><p>等这些都稳定后，再考虑 <code>fminsearch</code>、<code>patternsearch</code>、Simulink Design Optimization 或更复杂的自动整定工具。</p>`,11))])}const y=t(m,[["render",r]]);export{v as __pageData,y as default};
